import{_ as e,o as d,c,a4 as t}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"Go Little Book - 入门","description":"","frontmatter":{"date":"2018-11-22T10:02:33","title":"Go Little Book - 入门","categories":["go","go little book"],"tags":["go","go little book"]},"headers":[{"level":2,"title":"OSX / Linux","slug":"osx-linux","link":"#osx-linux","children":[]},{"level":2,"title":"Windows","slug":"windows","link":"#windows","children":[]}],"relativePath":"posts/go/go-little-book/getting-start.md","filePath":"posts/go/go-little-book/getting-start.md"}'),i={name:"posts/go/go-little-book/getting-start.md"};function l(a,o,r,s,n,p){return d(),c("div",null,[...o[0]||(o[0]=[t(`<h1 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to &quot;入门&quot;">​</a></h1><p>如果你想试试Go，你可以使用Go运行环境，它可以让你无需安装任何东西就可以在网上运行代码。这也是在Go论坛如StackOverflow中寻求帮助时，分享Go代码最常用的方式。</p><p>安装Go很简单。你可以从源码安装，但我建议你用一个已编译好的可执行文件。当你打开下载页面时，你可以看到不同平台的安装包。让我们避免使用这些并学习自己如何配置Go。然后你就会发现这不难。</p><p>除了简单的例子，Go被设计成只有你的代码在工作区时才能正常运行。这个工作区是有<code>bin</code>、<code>pkg</code>和<code>src</code>三个子目录的文件夹。你也许会想强制Go去适应你自己的风格 - 别想。</p><p>通常，我把我的项目放在<code>~/code</code>目录下。例如，<code>~/code/blog</code>是我的博客。对于Go来说，我的工作区是<code>~/code/go</code>，而我Go版本的博客会在~/code/go/src/blog下。因为这经常用到，我做了个符号链接，通过<code>~/code/blog</code>来访问它：</p><pre><code>ln -s ~/code/go/src/blog ~/code/blog
</code></pre><p>总之，无论你把你的项目放在哪，创建一个Go目录包含src子目录来放置你的项目。</p><h2 id="osx-linux" tabindex="-1">OSX / Linux <a class="header-anchor" href="#osx-linux" aria-label="Permalink to &quot;OSX / Linux&quot;">​</a></h2><p>下载你平台对应<code>tar.gz</code>。OSX，你需要关心<code>go#.#.#.darwin-amd64-osx10.8.tar.gz</code>，其中<code>#.#.#</code>表示Go的最新版本。</p><p>通过<code>tar -C /usr/local -xzf go#.#.#.darwin-amd64-osx10.8.tar.gz</code>将文件解压到<code>/usr/local</code>目录。</p><p>设置两个环境变量：</p><ol><li><code>GOPATH</code>指向你的工作区，对我来说是<code>$HOME/code/go</code>。</li><li>我们需要将Go可执行文件的路径添加到<code>PATH</code>。</li></ol><p>你可以通过shell来完成设置：</p><pre><code>echo &#39;export GOPATH=$HOME/code/go&#39; &gt;&gt; $HOME/.profile
echo &#39;export PATH=$PATH:/usr/local/go/bin&#39; &gt;&gt; $HOME/.profile
</code></pre><p>为了使这些变量生效，你需要关闭并重新打开你的Shell，或者运行<code>source $HOME/.profile</code>命令。</p><p>输入<code>go version</code>,你会看到类似这样的输出<code>go version go1.3.3</code>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>下载最新的zip文件。如果你是x64系统，你需要下载<code>go#.#.#.windows-amd64.zip</code>，其中<code>#.#.#</code>表示Go的最新版本。</p><p>将其解压到你想要的位置。<code>c:\\Go</code>是个不错和选择。</p><p>Set up two environment variables: 设置两个环境变理：</p><ol><li><code>GOPATH</code> 指向你的工作区. 可以是这样的目录<code>c:\\users\\goku\\work\\go</code>。</li><li>添加 <code>c:\\Go\\bin</code> 至你的<code>PATH</code>环境变量中。</li></ol><p>环境变量可以通过<code>系统</code>控制面板中的<code>环境变量</code>按钮中的<code>高级</code>标签页来设置。某些版本的Windows通过<code>System</code>控制面板里面的<code>高级系统Settings</code>选项提供该控制面板。</p><p>打开一个命令行窗口，输入<code>go version</code>，你会看到类似这样的输出<code>go version go1.3.3 windows/amd64</code>。</p>`,23)])])}const h=e(i,[["render",l]]);export{u as __pageData,h as default};
